const fs=require('fs');
const {chromium}=require('playwright');
const base='https://plan-ex.ru/erpv2';
const out=process.env.RESULT_DIR||'feo_route_executor_acceptance_result';
const creds=JSON.parse(Buffer.from(process.env.P12_CREDENTIALS_B64||'','base64').toString('utf8')||'[]');
const dynamicMembershipId=Number(process.env.QA_DYNAMIC_MEMBERSHIP_ID||0);
const companyA=Number(process.env.QA_COMPANY_A_ID||0), companyB=Number(process.env.QA_COMPANY_B_ID||0);
const routeIds={component:Number(process.env.QA_ROUTE_COMPONENT_CREW_ID||0),direct:Number(process.env.QA_ROUTE_DIRECT_CREW_ID||0),hidden:Number(process.env.QA_ROUTE_HIDDEN_CREW_ID||0)};
const feoCounters=JSON.parse(Buffer.from(process.env.FEO_COUNTERS_B64||'','base64').toString('utf8')||'{}');
fs.mkdirSync(out,{recursive:true});const marks=[];
function mark(x){marks.push(x);console.log(x);fs.writeFileSync(`${out}/proof.txt`,marks.join('\n')+'\n');}
function must(v,m){if(!v)throw new Error(m);}
function appPath(url){const p=new URL(url).pathname;return p.startsWith('/erpv2')?(p.slice(6)||'/'):p;}
function stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object'){const o={};Object.keys(v).sort().forEach(k=>o[k]=stable(v[k]));return o;}return v;}
async function api(page,method,path,body){return page.evaluate(async x=>{const o={method:x.method,headers:{Accept:'application/json'},credentials:'same-origin'};if(x.body!==undefined){o.headers['Content-Type']='application/json';o.body=JSON.stringify(x.body);}const r=await fetch(x.url,o);let p={};try{p=await r.json();}catch(_){}return{status:r.status,payload:p};},{method,url:base+path,body});}
async function login(browser,role){const c=creds.find(x=>String(x.role||'').toUpperCase()===role);must(c,`${role} credential missing`);const context=await browser.newContext({viewport:{width:1440,height:1000},locale:'ru-RU'});const page=await context.newPage();let r=await page.goto(base+'/login',{waitUntil:'domcontentloaded',timeout:60000});must(r&&r.status()===200,'login page failed');await page.locator('input[name="login"]').fill(String(c.username));await page.locator('input[name="password"]').fill(String(c.password));await Promise.all([page.waitForNavigation({waitUntil:'domcontentloaded',timeout:60000}),page.locator('button[type="submit"]').click()]);must(appPath(page.url())!=='/login',`${role} login failed`);return{context,page};}
async function state(page){const r=await api(page,'GET','/company/roles-access/data');must(r.status===200&&Array.isArray(r.payload.roles)&&Array.isArray(r.payload.memberships),'roles state failed');return r.payload;}
async function saveRole(page,role,scopes,pages){const r=await api(page,'POST',`/company/roles-access/roles/${Number(role.id)}/save`,{name:role.name,pages:pages??role.pages??{},data_scopes:scopes,default_page_key:role.default_page_key||null});must(r.status===200&&r.payload.ok===true,'role save failed');}
async function saveMember(page,m,overrides){const r=await api(page,'POST',`/company/roles-access/memberships/${Number(m.id)}/save`,{role_id:Number(m.role_id),status:String(m.status),page_overrides:m.page_overrides||{},data_scope_overrides:overrides});must(r.status===200&&r.payload.ok===true,'membership override save failed');}
async function routeIdsOnPage(page){const r=await page.goto(base+'/company/route-executors',{waitUntil:'networkidle',timeout:60000});must(r&&r.status()===200,'route executors page failed');return (await page.locator('[data-route-executor-id]').evaluateAll(ns=>ns.map(n=>Number(n.dataset.routeExecutorId)).filter(Boolean))).sort((a,b)=>a-b);}
function hasSet(actual,want){return want.every(x=>actual.includes(x));}
async function feoProof(page){await page.goto(base+'/company/dashboard',{waitUntil:'networkidle',timeout:60000});const data=await page.evaluate(()=>{const parent=[...document.querySelectorAll('.nav-item.is-parent')].find(x=>String(x.querySelector('.nav-label')?.textContent||'').trim()==='Заявки ФЭО');if(!parent)return null;const sub=parent.nextElementSibling;const children={};for(const a of [...(sub?.querySelectorAll('a.nav-sub-item')||[])]){const p=new URL(a.href,location.href).pathname.replace(/^\/erpv2/,'');const b=a.querySelector('.nav-count.is-alert');children[p]=b?String(b.textContent||'').trim():'';}const pb=parent.querySelector('.nav-count.is-alert');return{children,parent:pb?String(pb.textContent||'').trim():''};});must(data,'FEO parent group missing');const mapping={'company.feo.requests':'/company/feo/requests','company.feo.map_placement':'/company/feo/requests/map-placement','company.feo.map':'/company/feo/requests/map','company.feo.utilizers':'/company/feo/utilizers','company.feo.costs':'/company/feo/requests/costs'};let sum=0;for(const [key,path] of Object.entries(mapping)){const expected=Number(feoCounters[key]||0);sum+=expected;const shown=String(data.children[path]||'');const expectedLabel=expected<=0?'':(expected>999?'999+':String(expected));must(shown===expectedLabel,`${key} badge mismatch expected=${expectedLabel} actual=${shown}`);}const parentLabel=sum<=0?'':(sum>999?'999+':String(sum));must(String(data.parent||'')===parentLabel,`FEO parent badge mismatch expected=${parentLabel} actual=${data.parent}`);mark('FEO_CHILD_BADGES=PASS');mark('FEO_PARENT_BADGE_SUM=PASS');mark('FEO_ZERO_BADGE_HIDDEN=PASS');fs.writeFileSync(`${out}/feo_badges.json`,JSON.stringify({expected:feoCounters,rendered:data,sum},null,2)+'\n');}
async function switchCompany(page,id){const s=page.locator('#active-company-switch');must(await s.count()===1,'company switch missing');await Promise.all([page.waitForNavigation({waitUntil:'domcontentloaded',timeout:60000}),s.selectOption(String(id))]);}
(async()=>{const browser=await chromium.launch({headless:true});let owner=null,dynamic=null;let roleBaseline=null,memberBaseline=null,roleChanged=false,memberChanged=false;try{
 owner=await login(browser,'OWNER');mark('REAL_LOGIN_OWNER=PASS');await owner.page.goto(base+'/company/roles-access',{waitUntil:'networkidle',timeout:60000});let s=await state(owner.page);const m=s.memberships.find(x=>Number(x.id)===dynamicMembershipId);must(m&&m.status==='active','dynamic membership missing');const role=s.roles.find(x=>Number(x.id)===Number(m.role_id));must(role&&!role.is_system&&!role.system_key,'dynamic role invalid');roleBaseline=JSON.parse(JSON.stringify(role));memberBaseline=JSON.parse(JSON.stringify(m));
 await feoProof(owner.page);
 const pages=Object.assign({},role.pages||{}, {'company.dashboard':true,'company.route_executors':true});
 let scopes=Object.assign({},role.data_scopes||{}, {contractor:'all',driver:'all',vehicle_unit:'all'});await saveRole(owner.page,role,scopes,pages);roleChanged=true;
 dynamic=await login(browser,'DYNAMIC');mark('ROUTE_EXECUTOR_DYNAMIC_ROLE=PASS');let ids=await routeIdsOnPage(dynamic.page);must(hasSet(ids,[routeIds.component,routeIds.direct,routeIds.hidden]),`ALL fixture visibility failed ${ids}`);mark('ROUTE_EXECUTOR_ALL=PASS');
 scopes=Object.assign({},scopes,{contractor:'own',driver:'own',vehicle_unit:'own'});await saveRole(owner.page,role,scopes,pages);ids=await routeIdsOnPage(dynamic.page);must(ids.includes(routeIds.component)&&ids.includes(routeIds.direct)&&!ids.includes(routeIds.hidden),`OWN fixture visibility failed ${ids}`);mark('ROUTE_EXECUTOR_ONLY_OWN=PASS');mark('ROUTE_EXECUTOR_DIRECT_RESPONSIBILITY=PASS');
 scopes=Object.assign({},scopes,{driver:'none'});await saveRole(owner.page,role,scopes,pages);ids=await routeIdsOnPage(dynamic.page);must(!ids.includes(routeIds.component)&&!ids.includes(routeIds.direct)&&!ids.includes(routeIds.hidden),`NONE fixture visibility failed ${ids}`);mark('ROUTE_EXECUTOR_NONE=PASS');
 const overrides=Object.assign({},memberBaseline.data_scope_overrides||{}, {driver:'own'});await saveMember(owner.page,memberBaseline,overrides);memberChanged=true;ids=await routeIdsOnPage(dynamic.page);must(ids.includes(routeIds.component)&&ids.includes(routeIds.direct)&&!ids.includes(routeIds.hidden),`personal override visibility failed ${ids}`);mark('ROUTE_EXECUTOR_PERSONAL_OVERRIDE=PASS');
 await saveMember(owner.page,memberBaseline,memberBaseline.data_scope_overrides||{});memberChanged=false;
 await saveRole(owner.page,role,roleBaseline.data_scopes||{},roleBaseline.pages||{});roleChanged=false;
 ids=await routeIdsOnPage(owner.page);must(hasSet(ids,[routeIds.component,routeIds.direct,routeIds.hidden]),'owner lost full route access');mark('ROUTE_EXECUTOR_OWNER_ALL=PASS');
 await owner.page.goto(base+'/company/dashboard',{waitUntil:'networkidle',timeout:60000});await switchCompany(owner.page,companyB);const denied=await owner.page.goto(base+'/company/route-executors',{waitUntil:'domcontentloaded',timeout:60000});must(denied&&denied.status()===403,`company B route-executors denial expected 403 got ${denied&&denied.status()}`);const foreignText=String(await owner.page.locator('body').innerText());const routeNamespace=`QA Route ${process.env.GITHUB_RUN_ID||''} `;must(!foreignText.includes(routeNamespace),`company A route namespace leaked to company B response: ${routeNamespace}`);await owner.page.goto(base+'/company/dashboard',{waitUntil:'networkidle',timeout:60000});await switchCompany(owner.page,companyA);mark('CROSS_COMPANY_LEAKAGE=NO');
 mark('QA_BROWSER_RESIDUE=0');
 }finally{try{if(owner&&memberChanged)await saveMember(owner.page,memberBaseline,memberBaseline.data_scope_overrides||{});}catch(e){console.error('member restore',e.message);}try{if(owner&&roleChanged)await saveRole(owner.page,roleBaseline,roleBaseline.data_scopes||{},roleBaseline.pages||{});}catch(e){console.error('role restore',e.message);}if(dynamic)await dynamic.context.close();if(owner)await owner.context.close();await browser.close();}})().catch(e=>{console.error(e.stack||e);process.exit(1);});
